/**
 * Schematic is a visual diagram editor component for drawing system schematics, control
 * flows, and process diagrams. Schematics support interactive symbols, connection
 * handles, and dynamic state visualization.
 */
export const schematicZ = z.object({
  /** key is the unique identifier for this schematic. */
  key: keyZ.default(uuid.create),
  /** name is a human-readable name for the schematic. */
  name: z.string().min(1, "name is required"),
  /** nodes contains all diagram nodes in the schematic. */
  nodes: nodeZ.array().default(() => []),
  /** edges contains all connections between nodes. */
  edges: edgeZ.array().default(() => []),
  /**
   * configs contains per-node configuration keyed by node key. The variant of each
   * value selects the symbol it configures.
   */
  configs: caseconv.preserveKeys(z.record(z.string(), nodeConfigZ).default(() => ({}))),
  /** group is the group the schematic sits in, if any. */
  group: group.keyZ.optional(),
  /** project is the project that holds the schematic. */
  project: project.keyZ.optional(),
});
export interface Schematic extends z.infer<typeof schematicZ> {}
export interface New extends z.input<typeof schematicZ> {}

/** RetrieveResponse holds the schematics a RetrieveRequest selects. */
export const retrieveResponseZ = z.object({
  /** schematics are the schematics the request selects. */
  schematics: schematicZ.array().default(() => []),
});
export interface RetrieveResponse extends z.infer<typeof retrieveResponseZ> {}

export const resourceID = resource.createIDFactory<Key>("schematic");
export const TYPE_RESOURCE_ID = resourceID("");
